/*
 * Shared by the HUD library simulator programs (test_hud.c, test_hud_draw.c, test_hud_em10ii.c), each
 * including it once: the mock register block of fw.S, a bump heap behind the malloc mock, the layer-1
 * buffers and GUI words as plain memory at the target's firmware addresses, and the dump output.
 * images.c (generated by test_hud_sim.py from the stock firmware) holds the image table.
 */
#ifndef _SIM_HUD_H
#define _SIM_HUD_H

#include <hud.h>

#define SIM_U8(a) (*(volatile uint8_t *)(a))
#define SIM_U16(a) (*(volatile uint16_t *)(a))
#define SIM_U32(a) (*(volatile uint32_t *)(a))

#define SIM_PITCH 896
#define SIM_GUI 0x33		/* what the "GUI" painted */

#define SIM_VRAM_TABLE FW_GPI_LAYER_VRAM
#define SIM_FONT_RES FW_GPI_FONT_RES
#define SIM_IMAGE_TABLE FW_GUI_IMAGE_TABLE
#define SIM_LAYER_BPP FW_GPI_LAYER_BPP
#define SIM_DRAW_BUF FW_GPI_DRAW_BUF
#define SIM_HIDE_MASK FW_GPI_HIDE_MASK
#define SIM_ONE_MODE FW_GPI_ONE_MODE
#define SIM_ONE_LAYER FW_GPI_ONE_LAYER
#define SIM_ONE_BUF FW_GPI_ONE_BUF
#define SIM_SUPER FW_GUI_SUPER
#define SIM_STATE FW_GUI_STATE

#if FENYKL_TARGET_EM10II
#define SIM_BUF0 0xA1E00000u
#define SIM_BUF1 0xA1F00000u
#define SIM_VRAM0 0x619ADF88u		/* the GUI's own place for the handles */
#define SIM_PROP_INFO (FW_PROP_TABLE + 8u * (0x8321u >> 4) + 4u)
#define SIM_INFO_BASIC 1
#define SIM_INFO_CUSTOM1 0x11
#define SIM_INFO_IMAGE 0
static volatile int8_t sim_info;	/* the INFO screen property's object */
#else
#define SIM_BUF0 0xA0800000u
#define SIM_BUF1 0xA0900000u
#define SIM_VRAM0 0x6066E100u
#endif

extern const void *const sim_images[];		/* images.c: [id] -> struct gui_image */

uint32_t sim_exit_code = 99;
volatile uint32_t mreg[5];
static uint8_t sim_heap[0x10000] __attribute__((aligned(4)));
static unsigned int sim_heap_used;

void sim_write(const void *buf, unsigned int len);

uint32_t c_malloc(void)
{
	unsigned int size = (mreg[2] + 3) & ~3u;

	if (sim_heap_used + size > sizeof(sim_heap))
		return 0;
	sim_heap_used += size;
	return (uint32_t)&sim_heap[sim_heap_used - size];
}

uint32_t c_free(void)
{
	return 0;
}

static volatile uint8_t *sim_px(uint32_t buf, const struct fenykl_hud_elem *e, int r, int c)
{
	return (volatile uint8_t *)(buf + (e->y + r) * SIM_PITCH + e->x + c);
}

static void sim_fill(uint32_t buf, const struct fenykl_hud_elem *e, uint8_t v)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			*sim_px(buf, e, r, c) = v;
}

/* 1 if the rectangle in buf is all v */
static int sim_all(uint32_t buf, const struct fenykl_hud_elem *e, uint8_t v)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			if (*sim_px(buf, e, r, c) != v)
				return 0;
	return 1;
}

/* 1 if the rectangle is the same in both buffers */
static int sim_same(const struct fenykl_hud_elem *e)
{
	for (int r = 0; r < e->h; r++)
		for (int c = 0; c < e->w; c++)
			if (*sim_px(SIM_BUF0, e, r, c) != *sim_px(SIM_BUF1, e, r, c))
				return 0;
	return 1;
}

static char *sim_dec(char *o, int v)
{
	char s[12];
	int n = 0;

	if (v < 0)
		*o++ = '-', v = -v;
	do
		s[n++] = (char)('0' + v % 10);
	while ((v /= 10));
	while (n)
		*o++ = s[--n];
	*o++ = ' ';
	return o;
}

#if FENYKL_TARGET_EM10II
/* Live view with the info display on the LCD, INFO screen basic info. */
static void sim_setup_gui(void)
{
	for (unsigned int b = 0; b < 2; b++) {
		uint32_t v = SIM_VRAM0 + 16 * b;	/* {pdata, plane, w, h, x, y} */

		SIM_U32(v) = b ? SIM_BUF1 : SIM_BUF0;
		SIM_U32(v + 4) = 2;
		SIM_U16(v + 8) = SIM_PITCH;
		SIM_U16(v + 10) = 600;
		SIM_U32(SIM_VRAM_TABLE + 8 + 4 * b) = v;
	}
	SIM_U8(SIM_SUPER) = 0x01;
	SIM_U8(SIM_STATE) = 0x08;
	SIM_U32(FW_GUI_DISP_REQ) = 0xF001;
	SIM_U32(FW_DISP_DEVICE) = 1;
	SIM_U16(FW_PROP_OVERRIDE_VALID) = 0;
	SIM_U32(SIM_PROP_INFO) = (uint32_t)&sim_info;
	sim_info = SIM_INFO_BASIC;
}

/* A screen without the HUD (image only), and one with it (histogram). */
static void sim_set_hidden(void)
{
	sim_info = SIM_INFO_IMAGE;
}

static void sim_set_visible(void)
{
	sim_info = SIM_INFO_CUSTOM1;
}
#else
/* Basic screen (0x03). */
static void sim_setup_gui(void)
{
	for (unsigned int b = 0; b < 2; b++) {
		uint32_t v = SIM_VRAM0 + 16 * b;	/* {plane, w, h, pdata} */

		SIM_U32(v) = 2;
		SIM_U16(v + 4) = SIM_PITCH;
		SIM_U16(v + 6) = 600;
		SIM_U32(v + 8) = b ? SIM_BUF1 : SIM_BUF0;
		SIM_U32(SIM_VRAM_TABLE + 8 + 4 * b) = v;
	}
	SIM_U8(SIM_SUPER) = 0x02;
	SIM_U8(SIM_STATE) = 0x03;
}

/* Multi View (0x06), and Histogram (0x04). */
static void sim_set_hidden(void)
{
	SIM_U8(SIM_STATE) = 0x06;
}

static void sim_set_visible(void)
{
	SIM_U8(SIM_STATE) = 0x04;
}
#endif

/* Two layer-1 buffers, the image table, a visible screen, nothing masked; no font. */
static void sim_setup_memory(void)
{
	sim_setup_gui();
	SIM_U32(SIM_IMAGE_TABLE) = (uint32_t)sim_images;
	SIM_U8(SIM_LAYER_BPP + 1) = 8;
	SIM_U8(SIM_DRAW_BUF) = 0;
	SIM_U16(SIM_HIDE_MASK) = 0;
	SIM_U8(SIM_ONE_MODE) = 0;
}

#endif
